class _TopContext:
    """记下 ``run_action(..., pipeline_override=...)`` 的假 context（回顶部**方向**断言用）。

    ``hooks_100.FakeContext`` 只记 ``(name, box)``，会把 ``pipeline_override`` 丢掉；
    回顶部守卫要证的是「手势真的**向上**」（begin.y < end.y），所以这里单独记 kwargs。
    """

    def __init__(self) -> None:
        self.overrides: list = []
        self.calls: list = []

    def override_next(self, node_name, next_list) -> None:  # noqa: D102
        self.overrides.append((node_name, list(next_list)))

    def run_action(self, name, box=None, **kwargs) -> bool:  # noqa: D102
        self.calls.append((name, box, dict(kwargs)))
        return True


def _mode_detail(impl, ctx, task: int, mode: str, frame, node: str = "LordsScanPage") -> dict:
    """换一帧跑一个导航 mode，返回 detail + ``_box``（= 命中的框；没命中为 ``None``）。"""
    with _frame(impl, frame):
        res = impl.LordsProgressRecognition().analyze(
            ctx, _fakes().FakeArgv(reco_param={"mode": mode}, task_id=task, node_name=node)
        )
    detail = _detail(res)
    detail["_box"] = None if res.box is None else list(res.box)
    return detail


def _scroll_top_action(impl, ctx, task: int) -> bool:
    """跑一次 ``do=scroll_top``（回顶部上滚）。"""
    return impl.LordsUnlockAction().run(
        ctx, _fakes().FakeArgv(act_param={"do": impl.DO_SCROLL_TOP}, task_id=task)
    )


def _rewind_failures(impl=None, nav=None) -> list:
    """★挂点 ⑥-a★ 每页扫描前先**回顶部**（有界 + 可验证；真机 484 第 6 轮）。

    真机现场：战后列表停在**最后 5 行**（``004_trace04.png``），第 2 轮「领主战」只向下滚
    6 次就判「到底」—— 而画面上还有 妖狐讨伐 3/4（``accept6_yaohu_3of4.png``）。
    「到底」是**相对滚动位置**的概念：不回顶部，第二轮的「到底」毫无意义。

    断言：
      * 数据：``SCROLL_PLAN.max_rewinds_per_page`` 有界（8..60）且真源 == 安装态快照；
      * 状态机：``NavState()`` / ``begin_round`` / ``advance_tab`` 都重新武装回顶部；
        ``observe_rewind`` 从底部帧到顶部帧（出现新行）⇒ 未到顶；同屏两代 ⇒ 已到顶部；
      * agent：上一轮已扫完、新一轮关轮后，``mode=top`` 在底部帧上**命中**（不是直接「已到顶部」），
        动作 ``do=scroll_top`` 真的走 ``LordsScrollNode`` 且手势**向上**（begin.y < end.y，
        == ``SCROLL_PLAN.up_begin/up_end``），且**不吃**向下扫的账（scrolls_in_page/scroll_gen 不动）；
      * 到顶后 ``mode=top`` 不命中、日志/ detail 说得出「上滚几次 + 连续几代无位移」；
      * **有界**：一直读得到「新行」（永远到不了顶）⇒ 预算用尽**带原因收工**
        （原因含「回顶部失败 / 扫描不完整」，且 override 到 LordsStop），绝不无限上滚。
    """
    impl = _impl() if impl is None else impl
    nav = _lords_nav() if nav is None else nav
    fakes = _fakes()
    msgs: list = []
    plan = nav.SCROLL_PLAN

    # (a) 数据：预算有界 + 真源/安装态快照一致
    if not (8 <= int(plan.max_rewinds_per_page) <= 60):
        msgs.append(
            f"SCROLL_PLAN.max_rewinds_per_page = {plan.max_rewinds_per_page} 不在 8..60 —— "
            f"回顶部必须有界（46 位成员 / 一次上滚露 ~2 行 ≈ 23）"
        )
    snap = getattr(impl, "_NavSnapshotLogic", None)
    snap_plan = getattr(snap, "SCROLL_PLAN", None) if snap is not None else None
    if snap_plan is None or int(snap_plan.max_rewinds_per_page) != int(plan.max_rewinds_per_page):
        msgs.append(
            f"安装态快照 SCROLL_PLAN.max_rewinds_per_page = "
            f"{getattr(snap_plan, 'max_rewinds_per_page', None)!r} != 真源 {plan.max_rewinds_per_page}"
        )

    # (b) 状态机：每页都重新武装；到底判据是「上滚两代都没新行/没位移」
    st = nav.NavState()
    if not st.rewind_pending():
        msgs.append("NavState() 一开始 rewind_done=True —— 第一页不会回顶部（真机启动时就在底部）")
    st.begin_round(1.0)
    if not st.rewind_pending():
        msgs.append("begin_round 没有重新武装「回顶部」—— 新一轮会从战后位置往下扫")
    bottom_rows = fakes._rows_of(ACCEPT6_BOTTOM_FRAME)
    top_rows = fakes._rows_of(ACCEPT6_LORD_TOP_FRAME)
    at_top, why = st.observe_rewind(bottom_rows)
    if at_top:
        msgs.append(f"底部帧（最后 5 行）被当成「已到顶部」：{why!r}")
    st.note_rewind_scroll(2.0)
    at_top, why = st.observe_rewind(top_rows)
    if at_top or "新行" not in why:
        msgs.append(f"上滚后出现新行（还有上面的行）却没判「未到顶」：{why!r}")
    st.note_rewind_scroll(3.0)
    at_top, why = st.observe_rewind(top_rows)
    if at_top:
        msgs.append(f"只连续 1 代无新行/无位移就判到顶（stable_times=2）：{why!r}")
    st.note_rewind_scroll(4.0)
    at_top, why = st.observe_rewind(top_rows)
    if not at_top or "已到顶部" not in why:
        msgs.append(f"连续 2 代无新行/无位移却没判「已到顶部」：{why!r}")
    st2 = nav.NavState()
    st2.begin_round(1.0)
    st2.rewind_done = True
    st2.advance_tab(2.0)
    if not st2.rewind_pending():
        msgs.append("advance_tab 到下一页时没有重新武装「回顶部」—— 第二页会沿用第一页的滚动位置")
    st3 = nav.NavState()
    st3.begin_round(1.0)
    st3.advance_tab(2.0)
    if st3.top_unconfirmed != 1:
        msgs.append(
            f"没确认到顶就收尾的页数 = {st3.top_unconfirmed}（应为 1）—— 扫描完整性账没记上"
        )

    # (c) agent：战后停在底部 ⇒ 新一轮先回顶部（动作真的向上）
    task = 122601
    impl.reset_sessions()
    with fakes.FakeClock(20000.0) as clock, fakes.FakeSleeper():
        ctx = _TopContext()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is None:
            return msgs + ["取不到导航状态（_nav_state）—— 回顶部守卫无从注入"]
        state.complete_scan(0, clock.now)
        session.round_index = 1                      # 一轮已关 ⇒ 新一轮该重扫
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            d0 = _mode_detail(impl, ctx, task, impl.MODE_TOP, ACCEPT6_BOTTOM_FRAME)
        if d0.get("scanning") is not True:
            msgs.append(f"扫描期 mode=top 的 detail.scanning 应为 True（{d0!r}）")
        if d0.get("round_rearmed") is not True:
            msgs.append(f"新一轮没 arm sweep（detail.round_rearmed={d0.get('round_rearmed')!r}）")
        if "轮开始：扫描重新武装" not in buf.getvalue():
            msgs.append(f"新一轮没有「第 N 轮开始」日志：{buf.getvalue()[-200:]!r}")
        if d0.get("stop"):
            msgs.append(f"刚回到扫描期就收工（{d0.get('reason')!r}）")
        if tuple(d0.get("_box") or ()) != (0, 0, 0, 0):
            msgs.append(f"底部帧上 mode=top 应命中（box=[0,0,0,0]），实际 {d0.get('_box')!r}")
        if state.rewind_scrolls != 0 or state.rewind_done:
            msgs.append(f"还没滚就记成已到顶（rewind_scrolls={state.rewind_scrolls}）")
        if not _scroll_top_action(impl, ctx, task):
            msgs.append("do=scroll_top 的动作返回 False")
        if state.rewind_scrolls != 1:
            msgs.append(f"回顶部上滚一次后 rewind_scrolls 应为 1，实际 {state.rewind_scrolls}")
        if state.scrolls_in_page != 0 or state.scroll_gen != 0:
            msgs.append(
                f"回顶部吃了向下扫的账（scrolls_in_page={state.scrolls_in_page} / "
                f"scroll_gen={state.scroll_gen}）—— 「到底」世代会被上滚推进"
            )
        if not ctx.calls:
            msgs.append("do=scroll_top 没有调用滚动手势节点")
        else:
            name, _box, kwargs = ctx.calls[-1]
            if name != impl.SCROLL_NODE:
                msgs.append(f"回顶部调用了 {name!r}，应为 {impl.SCROLL_NODE!r}")
            override = (kwargs.get("pipeline_override") or {}).get(impl.SCROLL_NODE) or {}
            param = (override.get("action") or {}).get("param") or {}
            begin, end = param.get("begin"), param.get("end")
            if not begin or not end:
                msgs.append(f"回顶部没有用 pipeline_override 盖手势几何（{param!r}）")
            elif int(end[1]) <= int(begin[1]):
                msgs.append(
                    f"回顶部的手势是**向下**的（begin={begin} → end={end}）—— 会让列表越滚越远"
                )
            elif tuple(begin) != tuple(plan.up_begin) or tuple(end) != tuple(plan.up_end):
                msgs.append(
                    f"回顶部几何应 == SCROLL_PLAN.up_begin/up_end（{plan.up_begin}→{plan.up_end}），"
                    f"实际 {begin}→{end}"
                )
        clock.advance(float(plan.min_interval_sec) + 0.5)

        # 到顶：出现「顶部帧」（上面的行）后同屏两代 ⇒ 已到顶部、mode=top 不再命中
        for _step in range(2):
            d = _mode_detail(impl, ctx, task, impl.MODE_TOP, ACCEPT6_LORD_TOP_FRAME)
            if d.get("stop"):
                msgs.append(f"回顶部途中收工（{d.get('reason')!r}）")
                break
            if not _scroll_top_action(impl, ctx, task):
                msgs.append("回顶部途中 do=scroll_top 返回 False")
                break
            clock.advance(float(plan.min_interval_sec) + 0.5)
        d_final = _mode_detail(impl, ctx, task, impl.MODE_TOP, ACCEPT6_LORD_TOP_FRAME)
        if not state.rewind_done:
            msgs.append("连续两代同屏后 rewind_done 仍为 False —— 永远到不了顶")
        if "已到顶部" not in str(d_final.get("rewind_reason") or ""):
            msgs.append(f"到顶理由没说「已到顶部」：{d_final.get('rewind_reason')!r}")
        if d_final.get("_box") is not None:
            msgs.append(f"已到顶部后 mode=top 不该再命中/给框（{d_final.get('_box')!r}）")

        # (d) 有界：一直有「新行」⇒ 永远到不了顶 ⇒ 预算用尽带原因收工
        impl.reset_sessions()
        task2 = 122602
        ctx2 = _TopContext()
        session2 = impl._session(task2)
        state2 = impl._nav_state(session2)
        state2.begin_round(clock.now)
        last: dict = {}
        for step in range(int(plan.max_rewinds_per_page) + 2):
            frame = (
                ("领主战", [135, 388, 90, 35]),
                ("降临讨伐", [481, 389, 117, 33]),
                ("更新列表", [615, 328, 82, 28]),
                (f"新行{step}", [201, 640, 165, 28]), ("通关数1/4", [547, 688, 127, 28]),
            )
            last = _mode_detail(impl, ctx2, task2, impl.MODE_TOP, frame)
            if last.get("stop"):
                break
            if not _scroll_top_action(impl, ctx2, task2):
                msgs.append("有界剧本里 do=scroll_top 返回 False")
                break
            clock.advance(float(plan.min_interval_sec) + 0.5)
        if not last.get("stop"):
            msgs.append("回顶部永远到不了顶却从不收工 —— 会无限上滚（必须有界）")
        else:
            reason = str(last.get("reason") or "")
            for needle in ("回顶部失败", "扫描不完整", "未确认回到顶部"):
                if needle not in reason:
                    msgs.append(f"回顶部失败的原因缺 {needle!r}：{reason!r}")
            if "滚动上限" in reason or "本页已滚" in reason:
                msgs.append(f"回顶部失败被写成「滚动上限」（病因指错）：{reason!r}")
            if not _stopped(ctx2, impl):
                msgs.append(f"回顶部失败没有 override 到 {impl.STOP_NODE}：{ctx2.overrides}")
        if state2.rewind_scrolls > plan.max_rewinds_per_page:
            msgs.append(
                f"回顶部上滚 {state2.rewind_scrolls} 次 > 上限 {plan.max_rewinds_per_page} —— 边界失效"
            )
    impl.reset_sessions()
    return msgs


def probe_lords_rewind_to_top() -> bool:
    """★挂点 ⑥-a★ 每页扫描前先回顶部（有界 + 可验证）。"""
    return _rewind_failures() == []


def _tab_land_failures(impl=None, nav=None) -> list:
    """★挂点 ⑥-b★ **页签没切成功不许宣布「两个页签都扫到底」**（真机 484 第 6 轮）。

    现场：``L187 轮到降临讨伐`` 之后 **一次 `页签：click` 都没有**，同一帧「领主战」再读 3 次
    + 滚 2 次就收尾 ⇒「两页签共 4 行 / 目标 0」。断言：
      * 到底判据在**错的页签**上不推进（``sweep_index`` 不变、``sweep_done`` 仍 False、
        日志里没有「两个页签都扫到底」）；
      * 页签一直切不过去 ⇒ 有界收工，原因含「页签未切换」「扫描不完整」、override LordsStop，
        **不含**「滚动上限」；``nav.tab_switch_failed`` 记账。
    """
    impl = _impl() if impl is None else impl
    nav = _lords_nav() if nav is None else nav
    fakes = _fakes()
    msgs: list = []
    task = 122611
    impl.reset_sessions()
    with fakes.FakeClock(30000.0) as clock:
        ctx = fakes.FakeContext()
        reco = impl.LordsProgressRecognition()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is None:
            return ["取不到导航状态（_nav_state）—— 页签落地守卫无从注入"]
        state.complete_scan(0, clock.now)
        state.begin_round(clock.now)
        state.advance_tab(clock.now)                 # sweep_index=1（降临讨伐）
        state.rewind_done = True                      # 回顶部不在本守卫范围
        state.stable_scrolls = nav.SCROLL_PLAN.stable_times   # 假装这一页到底
        buf = io.StringIO()
        with _frame(impl, fakes.LIST_FRAME), contextlib.redirect_stdout(buf):
            end = reco.analyze(
                ctx,
                fakes.FakeArgv(
                    reco_param={"mode": "end"}, task_id=task, node_name="LordsListEnd"
                ),
            )
        log = buf.getvalue()
        end_detail = _detail(end)
        if end.box is not None:
            msgs.append("★页签没切成功时 mode=end 却命中了★ —— 不许宣布「两个页签都扫到底」")
        if state.sweep_done or state.sweep_index != 1:
            msgs.append(
                f"★页签没切成功却推进了扫描★（sweep_index={state.sweep_index}, "
                f"sweep_done={state.sweep_done}）—— 两页签共 4 行 / 目标 0 就是这么来的"
            )
        if "两个页签都扫到底" in log:
            msgs.append(f"★错的页签上宣布「两个页签都扫到底」★：{log[-200:]!r}")
        if "页签" not in str(end_detail.get("reason") or ""):
            msgs.append(f"mode=end 被拦下了，但理由没说清是页签：{end_detail.get('reason')!r}")

        # 页签一直切不过去（同一帧）：第一次 click 真的点，之后连续未确认 ⇒ 有界收工
        with _frame(impl, fakes.LIST_FRAME):
            first_detail = _detail(_tab(impl, ctx, task))
        if str(first_detail.get("action")) != nav.ACTION_CLICK:
            msgs.append(f"扫描期页签不对时第一次判决应为 click，实际 {first_detail.get('action')!r}")
        action = impl.LordsUnlockAction()
        if first_detail.get("box") is not None:
            if not action.run(
                ctx,
                fakes.FakeArgv(task_id=task, box=first_detail.get("box"), act_param={"do": "tab"}),
            ):
                msgs.append("do=tab 的动作返回 False")
        stuck_detail: dict = {}
        for _step in range(6):
            clock.advance(float(nav.TAB_CONFIRM_GRACE_SEC) + 0.5)
            with _frame(impl, fakes.LIST_FRAME):
                stuck_detail = _detail(_tab(impl, ctx, task))
            if stuck_detail.get("stop"):
                break
        if not stuck_detail.get("stop"):
            msgs.append("页签一直没切成功却从不收工 —— 会一直停在错的页签上")
        else:
            reason = str(stuck_detail.get("reason") or "")
            for needle in ("页签未切换", "扫描不完整"):
                if needle not in reason:
                    msgs.append(f"页签切不过去的收工原因缺 {needle!r}：{reason!r}")
            if "滚动" in reason or "本页已滚" in reason:
                msgs.append(f"页签切不过去却把原因写成滚动：{reason!r}")
            if not _stopped(ctx, impl):
                msgs.append(f"页签切不过去没有 override 到 {impl.STOP_NODE}：{ctx.overrides}")
        if not state.tab_switch_failed:
            msgs.append("页签切不过去没有记账（tab_switch_failed=False）—— 零目标原因里会漏这一条")
    impl.reset_sessions()
    return msgs


def probe_lords_tab_switch_must_land() -> bool:
    """★挂点 ⑥-b★ 页签没切成功 ⇒ 不许宣布「两个页签都扫到底」。"""
    return _tab_land_failures() == []


def _zero_reason_failures(impl=None, nav=None) -> list:
    """★挂点 ⑥-c★ 零目标收工的**原因必须指对病因**（真机 484 第 6 轮：空滚 80 次 / 7 分 54 秒）。

    修前理由写成「本页已滚 80 次（上限 80）仍未到底」—— 那不是滚动的问题，是**扫描不完整**
    （有行被徽标剔掉 / 没回顶 / 页签没切）。断言：
      * 扫描不完整 + 零目标 ⇒ 原因含「扫描不完整」「本轮零目标」「数据与画面可能不一致」
        以及具体量（徽标 3 行 / 未回顶 2 页 / 页签未切换），并收工 override；
      * **不含**「滚动上限 / 本页已滚」；
      * 反过来：完整扫描 + 零目标（全是不认识的行）⇒ 原因是「零目标」，不许冒充「扫描不完整」。
    """
    impl = _impl() if impl is None else impl
    nav = _lords_nav() if nav is None else nav
    fakes = _fakes()
    msgs: list = []
    lu = fakes._lords_unlock()
    # 真机第 2 轮「读到 4 行、目标 0」的形状：一行花名册外（日志里的 ``I``）+ 两行 M 与静态表冲突
    # （拿不到档 ⇒ 不规划）+ 一行已 M/M（不产生目标）⇒ ``plan.targets == ()`` 且 ``all_done`` False。
    rows = (
        lu.RowReading("I", 1, 4, (0, 0, 1, 1), (0, 0, 1, 1)),
        lu.RowReading("妖狐讨伐", 1, 3, (0, 0, 1, 1), (0, 0, 1, 1)),
        lu.RowReading("艾基尔·嫉妒讨伐", 2, 3, (0, 0, 1, 1), (0, 0, 1, 1)),
        lu.RowReading("八岐大蛇讨伐", 4, 4, (0, 0, 1, 1), (0, 0, 1, 1)),
    )
    synth = impl._synthesize_items(rows)
    logic = impl._logic()

    def _run_zero(task, dropped, top_unconfirmed, tab_failed):
        impl.reset_sessions()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is None:
            return None, None, None
        state.complete_scan(0, 0.0)
        state.begin_round(1.0)
        state.dropped_in_scan = dropped
        state.top_unconfirmed = top_unconfirmed
        state.tab_switch_failed = tab_failed
        ctx = fakes.FakeContext()
        res = impl.LordsProgressRecognition()._read(
            synth,
            ctx,
            fakes.FakeArgv(reco_param={"mode": "read"}, task_id=task),
            session,
            logic,
            synthesized=True,
        )
        return _detail(res), ctx, session

    detail, ctx, session = _run_zero(122621, 3, 2, True)
    if detail is None:
        return msgs + ["取不到导航状态（_nav_state）—— 零目标原因守卫无从注入"]
    reason = str(detail.get("reason") or "")
    if not detail.get("stop"):
        msgs.append(f"零目标 + 扫描不完整却没判收工（detail={detail!r}）")
    for needle in ("扫描不完整", "本轮零目标", "数据与画面可能不一致", "有行被徽标剔除 3 行",
                   "未确认回到顶部 2 页", "页签未切换"):
        if needle not in reason:
            msgs.append(f"零目标收工原因缺 {needle!r}：{reason!r}")
    if "滚动上限" in reason or "本页已滚" in reason:
        msgs.append(f"★零目标收工又落回「滚动上限」文案★：{reason!r}")
    if not _stopped(ctx, impl):
        msgs.append(f"零目标收工没有 override 到 {impl.STOP_NODE}：{ctx.overrides}")
    if not session.stop_requested:
        msgs.append("零目标收工没置「已判收工」—— 动作会去点一个空框")

    detail2, ctx2, _session2 = _run_zero(122622, 0, 0, False)
    reason2 = str((detail2 or {}).get("reason") or "")
    if "零目标" not in reason2:
        msgs.append(f"完整扫描 + 零目标却没说「零目标」：{reason2!r}")
    if "扫描不完整" in reason2:
        msgs.append(f"完整扫描的零目标被误报成「扫描不完整」：{reason2!r}")
    impl.reset_sessions()
    return msgs


def probe_lords_zero_target_right_reason() -> bool:
    """★挂点 ⑥-c★ 零目标收工原因指对病因（不是「滚动上限」）。"""
    return _zero_reason_failures() == []


def _arm_order_failures(impl=None) -> list:
    """★挂点 ⑥-d★ **arm sweep 必须在 plan / 点 row 之前**（真机 484 第 6 轮 L133–L136）。

    现场：``第 1 轮结束 → 单帧读 2 行 → 1 目标（妖狐 高级+）→ 点 row → 第 1 轮开始``
    ⇒ 第 1 轮**压根没扫**。断言：
      * 关轮的那一帧 ``mode=read`` **不命中**（``box=None``），``session.targets`` 为空，
        单帧 plan 只进 ``plans_discarded``（不许落地成目标）；
      * 紧接着 ``mode=pick`` 不命中（点不出行）；
      * 下一次 ``mode=tab`` 打「第 N 轮开始：扫描重新武装」，且整段日志里**没有任何 `点 row`**
        出现在它前面（arm 之前一次目标点击都不许发生）。
    """
    impl = _impl() if impl is None else impl
    fakes = _fakes()
    msgs: list = []
    task = 122631
    impl.reset_sessions()
    with fakes.FakeClock(50000.0) as clock:
        ctx = fakes.FakeContext()
        reco = impl.LordsProgressRecognition()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is None:
            return ["取不到导航状态（_nav_state）—— arm 顺序守卫无从注入"]
        state.complete_scan(0, clock.now)
        session.round_index = 1                       # 上一轮已扫完并关轮
        session.sessions_played = 1                   # 这一轮已经打过 1 场
        session.sessions_at_last_read = 0
        session.attempts_since_read = 1
        session.prev_cleared = {}
        buf = io.StringIO()
        with _frame(impl, fakes.LIST_FRAME), contextlib.redirect_stdout(buf):
            read = reco.analyze(
                ctx, fakes.FakeArgv(reco_param={"mode": "read"}, task_id=task)
            )
            pick = reco.analyze(
                ctx,
                fakes.FakeArgv(
                    reco_param={"mode": "pick"}, task_id=task, node_name="LordsPickTarget"
                ),
            )
        log = buf.getvalue()
        read_detail = _detail(read)
        if session.round_index != 2:
            msgs.append(f"回列表这一帧没有关轮（round_index={session.round_index}，应为 2）")
        if "第 2 轮结束" not in log:
            msgs.append(f"关轮没打「第 2 轮结束」：{log[-200:]!r}")
        if read.box is not None:
            msgs.append(
                f"★关轮的那一帧 mode=read 命中了（box={read.box!r}）★ —— 会拿单帧读数点目标"
            )
        if read_detail.get("gate") != "scan_due":
            msgs.append(f"关轮后没有「先扫描」闸（gate={read_detail.get('gate')!r}）")
        if not read_detail.get("plans_discarded"):
            msgs.append("单帧 plan 没有留下「已作废」的证据（plans_discarded 为空，守卫会空转）")
        if session.targets:
            msgs.append(
                f"★关轮后仍按单帧读数落地了目标★：{session.targets!r} —— 第 1 轮压根没扫"
            )
        if pick.box is not None or (pick.detail or {}).get("what") == impl.WHAT_ROW:
            msgs.append(f"关轮后紧接的 pick 还能点出行（{pick.detail!r}）—— arm 之前不许点")

        buf2 = io.StringIO()
        with _frame(impl, fakes.LIST_FRAME), contextlib.redirect_stdout(buf2):
            reco.analyze(
                ctx,
                fakes.FakeArgv(
                    reco_param={"mode": "tab"}, task_id=task, node_name="LordsSwitchTab"
                ),
            )
        arm_log = buf2.getvalue()
        if "轮开始：扫描重新武装" not in arm_log:
            msgs.append(f"没有「第 N 轮开始：扫描重新武装」：{arm_log[-200:]!r}")
        if state.sweep_done or not state.page_pending(session.round_index):
            msgs.append(
                f"arm 后扫描应重新待办（sweep_done={state.sweep_done}, "
                f"page_pending={state.page_pending(session.round_index)}）"
            )
        if "点 row" in log or "点 row" in arm_log:
            msgs.append(
                f"★arm 之前出现了「点 row」★（第 1 轮用单帧 2 行就点了）—— 日志：{log[-200:]!r}"
            )
    impl.reset_sessions()
    return msgs


def probe_lords_arm_before_plan() -> bool:
    """★挂点 ⑥-d★ arm sweep 在 plan / 点 row 之前。"""
    return _arm_order_failures() == []


def _badge_bottom_failures(impl=None, nav=None) -> list:
    """★挂点 ⑥-e★ 被徽标剔掉的行**算「见到行」**：这一帧不许判「到底」。

    真机 484 第 6 轮：每帧都有 4~5 行读成 ``COMPLETE!!``，修前剔完就判「连续两帧无新行」⇒
    假到底。★#100 第 8 轮★：这一帧的**真名不在帧里**（OCR 没读到）⇒ 行名修复也救不回来，
    只能整行不读 —— 这一条守的是**安全线**（真名读不出时照旧拦「到底」/「全通」）。断言：
      * 有被剔行的一帧（哪怕列表**真的没动**）⇒ ``at_end=False``、``dropped_n>0``、
        ``dropped_in_scan`` 累加；
      * 连续两代「滚不动」⇒ ``bottom_unprovable``（**底不可证**）+ ``page_finished``（可收尾，
        按扫描不完整），且 ``at_end`` 仍是 False（**不是**「到底」）；
      * 对照：同样的帧**没有徽标**时两代就该判到底（证明守卫不是空转）。
    """
    impl = _impl() if impl is None else impl
    nav = _lords_nav() if nav is None else nav
    fakes = _fakes()
    msgs: list = []
    frame = (
        ("领主战", [135, 388, 90, 35]),
        ("降临讨伐", [481, 389, 117, 33]),
        ("更新列表", [615, 328, 82, 28]),
        ("艾基尔·嫉妒讨伐", [202, 640, 197, 28]), ("通关数1/4", [547, 688, 127, 28]),
        # ★真名**不在帧里**（OCR 没读到）+ 徽标贴着「通关数3/4」⇒ 行名修复也救不回来
        #   ⇒ 这一行必须整行不读（#100 第 8 轮：能修的先修，修不回来的照旧不读）。
        ("通关数3/4", [547, 1120, 127, 28]),
        ("COMPLETE!!", [15, 1112, 124, 24]),
    )
    clean = tuple(item for item in frame if item[0] != "COMPLETE!!")
    raw_rows, _orphans = impl._logic().group_progress_rows(frame)
    if "COMPLETE!!" not in [str(getattr(row, "name", "")) for row in raw_rows]:
        msgs.append(f"这一帧没能复现「行名读成 COMPLETE!!」：{[r.name for r in raw_rows]}")

    task = 122641
    impl.reset_sessions()
    with fakes.FakeClock(60000.0) as clock:
        ctx = fakes.FakeContext()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is None:
            return msgs + ["取不到导航状态（_nav_state）—— 徽标到底守卫无从注入"]
        state.begin_round(clock.now)
        state.rewind_done = True                      # 回顶部不在本守卫范围
        d1 = _mode_detail(impl, ctx, task, impl.MODE_PAGE, frame)
        if d1.get("dropped_n") != 1:
            msgs.append(f"被徽标剔掉的行数应为 1，实际 {d1.get('dropped_n')!r}：{d1!r}")
        if state.dropped_in_scan < 1:
            msgs.append("dropped_in_scan 没有累加 —— 本轮扫描的完整性账丢了")
        state.note_scroll(clock.now)
        d2 = _mode_detail(impl, ctx, task, impl.MODE_PAGE, frame)
        if d2.get("at_end"):
            msgs.append("★有行被徽标剔掉却判了「到底」★ —— 假到底（丢的那行可能正是 N<M）")
        state.note_scroll(clock.now)
        d3 = _mode_detail(impl, ctx, task, impl.MODE_PAGE, frame)
        if d3.get("at_end"):
            msgs.append("★连续两代有被剔行却判了「到底」★")
        if not (d3.get("bottom_unprovable") or state.bottom_unprovable):
            msgs.append(
                f"两代滚不动 + 有被剔行，却没判「底不可证」：{d3!r} —— 会一直滚到 80 次上限"
            )
        if not d3.get("page_finished"):
            msgs.append("底不可证时本页没有收尾出口（page_finished=False）—— 扫描无法结束")
        if "不许判到底" not in str(d3.get("end_reason") or ""):
            msgs.append(f"底不可证的读法没说「不许判到底」：{d3.get('end_reason')!r}")
        if "有行被徽标剔除" not in state.scan_incomplete_reason():
            msgs.append(f"扫描完整性账没点名徽标剔除：{state.scan_incomplete_reason()!r}")

        # 对照：同样的帧**去掉徽标** ⇒ 两代就该判到底（守卫不许空转）
        st_clean = nav.NavState()
        st_clean.begin_round(1.0)
        st_clean.rewind_done = True
        clean_rows = fakes._rows_of(clean)
        st_clean.observe(clean_rows)
        st_clean.note_scroll(2.0)
        at1, _why1 = st_clean.observe(clean_rows)
        st_clean.note_scroll(3.0)
        at2, _why2 = st_clean.observe(clean_rows)
        if at1 or not at2:
            msgs.append(
                f"对照帧（无徽标）两代没判到底（at1={at1} / at2={at2}）—— 守卫会把正常到底也挡掉"
            )
    impl.reset_sessions()
    return msgs


def probe_lords_badge_dropped_not_bottom() -> bool:
    """★挂点 ⑥-e★ 被徽标剔掉的行算「见到行」：这一帧不许判到底。"""
    return _badge_bottom_failures() == []


# ---------------------------------------------------------------------------
# ★真机 484 第 7 轮验收（``debug/lords_accept7.log``，19:2x–19:52）★：假收工
# ---------------------------------------------------------------------------
# 现场见模块 docstring。三条修法共用同一套注入手法：
#   整轮扫描读数（``RowReading``）→ ``_synthesize_items`` → ``_read(synthesized=True)``；
#   战后单帧 → 真实 OCR 帧 → ``mode=read``（``synthesized=False``）。
#
#: 基线/复核用的**整轮扫描读数**（行名都是花名册成员；含 ``橙悚机兵 1/4`` —— 真机 L1054 的
#: 关轮帧里它正好被徽标挤掉了）。``妖狐讨伐`` 只在基线里出现：用来抓「战后单帧覆盖基线」。
SCAN_A_ROWS: tuple = (
    ("橙悚机兵", 1, 4),
    ("妖狐讨伐", 1, 4),
    ("八岐大蛇讨伐", 4, 4),
)
