    ("降临讨伐", [481, 389, 117, 33]),
    ("更新列表", [615, 328, 82, 28]),
    ("橙悚机兵", [201, 640, 155, 28]), ("通关数1/4", [547, 688, 127, 28]),
    ("八岐大蛇讨伐", [201, 1072, 165, 28]), ("通关数4/4", [547, 1120, 126, 28]),
