#: 可读行只剩 1 行（``八岐大蛇讨伐 4/4``，与基线**一模一样**）。
POST_FIGHT_BADGE_FRAME: tuple = (
    ("领主战", [135, 388, 90, 35]),
    ("降临讨伐", [481, 389, 117, 33]),
    ("更新列表", [615, 328, 82, 28]),
    ("COMPLETE!!", [15, 496, 124, 24]), ("通关数4/4", [547, 544, 127, 28]),
    ("COMPLETE!!", [15, 640, 124, 24]), ("通关数4/4", [547, 688, 127, 28]),
    ("COMPLETE!!", [15, 784, 124, 24]), ("通关数4/4", [547, 832, 126, 28]),
    ("八岐大蛇讨伐", [201, 1072, 165, 28]), ("通关数4/4", [547, 1120, 126, 28]),
)


def _scan_readings(impl, triples) -> tuple:
    """``[(行名, N, M)]`` → 生产用的 ``RowReading``（坐标只是占位，合成帧自己算）。"""
    lu = impl._logic()
    return tuple(
        lu.RowReading(name, n, m, (0, 0, 1, 1), (0, 0, 1, 1)) for name, n, m in triples
    )


def _synth_scan(impl, triples) -> tuple:
    """走**生产同一条路**（``agent/lords_impl._synthesize_items``）把整轮读数变成合成帧。"""
    return tuple(impl._synthesize_items(_scan_readings(impl, triples)))


def _scan_read(impl, fakes, reco, ctx, task, session, triples):
    """模拟 ``mode=end`` 的交接：整轮累计读数当合成帧 → ``_read(synthesized=True)``。"""
    return reco._read(
        _synth_scan(impl, triples),
        ctx,
        fakes.FakeArgv(task_id=task, node_name="LordsListEnd"),
        session,
        impl._logic(),
        synthesized=True,
    )


def _post_fight_read(impl, fakes, reco, ctx, task, session, frame):
    """模拟「结算 → 详情 → 返回 → 列表」之后的 ``mode=read``（**局部读数**，不是完整扫描）。"""
    with _frame(impl, frame):
        return reco.analyze(ctx, fakes.FakeArgv(reco_param={"mode": "read"}, task_id=task))


def _gain_scan_only_failures(impl=None) -> list:
    """★挂点 30★ 战后单帧**不判进展**；有徽标剔除的**扫描帧**只允许「无法判断」。

    真机 484 第 7 轮（``debug/lords_accept7.log``）::

        L1054 [行名过滤（read）：3 行的行名读成了徽标]   ← 关轮那一帧只剩 1 行可读
        L1055 第 7 轮结束：本轮打 1 场，新解锁=无，连续无新解锁 1 轮
        L1211 第 8 轮结束：本轮打 1 场，新解锁=无，连续无新解锁 2 轮
        L1212 收工：连续 2 轮没有新解锁（兜底阈值 2，累计 8 场）—— 带原因收工

    第 7、8 场都真打了，但 ``round_gained(prev_cleared, 单帧)`` 用**战后单帧**跟全扫读数比，
    徽标剔行又让可读行只剩 1 行 ⇒ 漏判 ⇒ 假收工。断言（缺一条就是本票复发）：
      * 完整扫描帧（含 ``橙悚机兵 1/4``）⇒ ``round_gain="baseline"``、基线 = 3 行；
      * **干净**的战后单帧（没有 dropped）⇒ 关轮照常（``第 N 轮结束``），但 ``round_gain="not_scan"``、
        ``prev_cleared`` **一个键都不许变**、``no_progress`` **不累加**、不许收工；
      * 真机同形的战后单帧（3 行徽标剔除、只剩 1 行）⇒ 同上（``detail.dropped`` 有账）；
      * 完整扫描帧**但本轮扫描里有行被徽标剔除**（``nav.dropped_in_scan>0``）⇒
        ``round_gain="undecidable"``：**绝不累加 no_progress**、基线不动、``gain_pending`` 保持挂起。
    """
    impl = _impl() if impl is None else impl
    fakes = _fakes()
    msgs: list = []
    task = 122701
    impl.reset_sessions()
    with fakes.FakeClock(13000.0) as clock:
        ctx = fakes.FakeContext()
        reco = impl.LordsProgressRecognition()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is None:
            return ["取不到导航状态（_nav_state）—— 关轮判据守卫无从注入"]
        state.complete_scan(session.round_index, clock.now)   # 真机此刻扫描已收尾

        # ① 完整扫描（基线）
        first = _detail(_scan_read(impl, fakes, reco, ctx, task, session, SCAN_A_ROWS))
        if first.get("round_gain") != "baseline":
            msgs.append(f"第一次完整扫描应是 baseline，实际 round_gain={first.get('round_gain')!r}")
        want_base = {"橙悚机兵": 1, "妖狐讨伐": 1, "八岐大蛇讨伐": 4}
        if dict(session.prev_cleared) != want_base:
            msgs.append(
                f"完整扫描没把基线设成整轮读数：{session.prev_cleared!r}（应为 {want_base!r}）"
            )

        # ② 干净战后单帧：关轮照常，但**不判进展、不覆盖基线**
        session.sessions_played = 1
        session.sessions_at_last_read = 0
        session.attempts_since_read = 1                     # 点过行/档/挑战 ⇒ 这一帧会关本轮
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            clean = _detail(
                _post_fight_read(
                    impl, fakes, reco, ctx, task, session, POST_FIGHT_CLEAN_FRAME
                )
            )
        log = buf.getvalue()
        if session.round_index != 1:
            msgs.append(f"干净的战后单帧没关本轮：round_index={session.round_index}（应为 1）")
        if "第 1 轮结束" not in log:
            msgs.append(f"干净的战后单帧没打「第 1 轮结束」：{log[-300:]!r}")
        if clean.get("round_gain") != "not_scan":
            msgs.append(
                f"★战后单帧被判了进展★：round_gain={clean.get('round_gain')!r} —— "
                f"它不是完整扫描产出，不许更新 prev_cleared / 不许判 round_gained"
            )
        if dict(session.prev_cleared) != want_base:
            msgs.append(
                f"★prev_cleared 被战后单帧覆盖★：{session.prev_cleared!r}（应仍为 {want_base!r}）"
                f"—— 下一次完整扫描会拿局部读数当基线"
            )
        if session.no_progress_rounds != 0:
            msgs.append(
                f"★战后单帧累加了 no_progress★：{session.no_progress_rounds} 轮 —— 漏判的第 7/8 场"
                f"就是这样变成「连续 2 轮无新解锁」的"
            )
        if clean.get("stop") or _stopped(ctx, impl) or session.stop_requested:
            msgs.append(f"战后单帧却判了收工：{clean.get('reason')!r}")
        if not session.gain_pending:
            msgs.append("关轮后没置 gain_pending —— 新解锁永远不会被复核")

        # ③ 真机同形的战后单帧（3 行徽标剔除、只剩 1 行）
        session.sessions_played = 2
        session.attempts_since_read = 1
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            badge = _detail(
                _post_fight_read(
                    impl, fakes, reco, ctx, task, session, POST_FIGHT_BADGE_FRAME
                )
            )
        log = buf.getvalue()
        dropped_n = len(badge.get("dropped") or ())
        if dropped_n != 3:
            msgs.append(f"这一帧应以 3 行徽标剔除复现真机 L1054，实际 {dropped_n} 行")
        if "行名过滤" not in log:
            msgs.append(f"徽标剔行没打账：{log[-300:]!r}")
        if badge.get("round_gain") != "not_scan":
            msgs.append(
                f"★有 3 行徽标剔除的战后单帧被判了进展★：round_gain={badge.get('round_gain')!r}"
            )
        if dict(session.prev_cleared) != want_base:
            msgs.append(
                f"★prev_cleared 被「只剩 1 行」的战后单帧覆盖★：{session.prev_cleared!r}"
                f"（应仍为 {want_base!r}）"
            )
        if session.no_progress_rounds != 0:
            msgs.append(
                f"★徽标剔行的战后单帧累加了 no_progress★：{session.no_progress_rounds} 轮"
                f"—— 被剔掉的那几行很可能正是 N<M 的行"
            )
        if badge.get("stop") or session.stop_requested:
            msgs.append(f"徽标剔行的战后单帧却判了收工：{badge.get('reason')!r}")

        # ④ 完整扫描帧，但**本轮扫描有行被徽标剔除** ⇒ 只允许「无法判断」，绝不累加
        state.dropped_in_scan = 3                            # 本轮扫描里 3 行读成了徽标
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            undecidable = _detail(
                _scan_read(impl, fakes, reco, ctx, task, session, SCAN_A_ROWS)
            )
        log = buf.getvalue()
        if undecidable.get("round_gain") != "undecidable":
            msgs.append(
                f"★有 dropped 的完整扫描帧没被判「无法判断」★："
                f"round_gain={undecidable.get('round_gain')!r}（no_progress="
                f"{session.no_progress_rounds}）—— 被剔的很可能正是 N<M 的行"
            )
        if "无法判断" not in log:
            msgs.append(f"「无法判断」没写进日志（现场看不出这条兜底为什么没动）：{log[-300:]!r}")
        if session.no_progress_rounds != 0:
            msgs.append(
                f"★有 dropped 的完整扫描帧累加了 no_progress★：{session.no_progress_rounds} 轮"
            )
        if dict(session.prev_cleared) != want_base:
            msgs.append(f"「无法判断」时基线被动了：{session.prev_cleared!r}（应仍为 {want_base!r}）")
        if not session.gain_pending:
            msgs.append("「无法判断」后没保持 gain_pending（下一次干净扫描就不复核了）")
        if undecidable.get("stop") or _stopped(ctx, impl) or session.stop_requested:
            msgs.append(f"「无法判断」却判了收工：{undecidable.get('reason')!r}")
        state.dropped_in_scan = 0
    impl.reset_sessions()
    return msgs


def probe_lords_round_gain_scan_only() -> bool:
    """★挂点 30★ 关轮只认整轮扫描帧：战后单帧不判进展；dropped 帧只允许「无法判断」。"""
    return _gain_scan_only_failures() == []


def _gain_real_progress_failures(impl=None) -> list:
    """★挂点 31★ 两次**完整扫描**之间的真进展要认：``橙悚机兵 1/4 → 3/4``。

    真机 484 第 7 轮的反证：第 8 轮详情页自读 ``高级+=NEW / 高级=COMPLETE!!``（= 第 7 场把
    橙悚机兵推到了 3/4），屏幕上 ``橙悚机兵 3/4`` 仍是未通关行。断言：
      * 完整扫描 B vs 基线 A ⇒ ``round_gain="gained"``、``round_gained`` 点名 ``橙悚机兵``；
      * ``no_progress`` **归零**（上一轮的 1 轮无进展被真进展清掉）；
      * 基线前进到 B（``橙悚机兵: 3``）、``gain_pending`` 清零、不收工。
    """
    impl = _impl() if impl is None else impl
    fakes = _fakes()
    msgs: list = []
    task = 122702
    impl.reset_sessions()
    with fakes.FakeClock(17000.0) as clock:
        ctx = fakes.FakeContext()
        reco = impl.LordsProgressRecognition()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is None:
            return ["取不到导航状态（_nav_state）—— 真进展守卫无从注入"]
        state.complete_scan(session.round_index, clock.now)
        _scan_read(impl, fakes, reco, ctx, task, session, SCAN_A_ROWS)
        # 关一轮（战后单帧）：新解锁的判定挂起，等下一次完整扫描
        session.sessions_played = 1
        session.sessions_at_last_read = 0
        session.attempts_since_read = 1
        with contextlib.redirect_stdout(io.StringIO()):
            _post_fight_read(impl, fakes, reco, ctx, task, session, POST_FIGHT_BADGE_FRAME)
        session.no_progress_rounds = 1                       # 上一轮已经「无新解锁」

        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            got = _detail(_scan_read(impl, fakes, reco, ctx, task, session, SCAN_B_ROWS))
        log = buf.getvalue()
        if got.get("round_gain") != "gained":
            msgs.append(
                f"★完整扫描间的真进展没被认★：round_gain={got.get('round_gain')!r}"
                f"（橙悚机兵 1/4 → 3/4 应判 gained）"
            )
        if session.no_progress_rounds != 0:
            msgs.append(
                f"★真进展后 no_progress 没归零★：{session.no_progress_rounds} 轮 —— "
                f"会把「打了但没读到」的轮次越攒越多"
            )
        if dict(session.prev_cleared).get("橙悚机兵") != 3:
            msgs.append(
                f"基线没前进到这一次完整扫描：{session.prev_cleared!r}"
                f"（橙悚机兵 应为 3）"
            )
        if session.gain_pending:
            msgs.append("判过之后 gain_pending 还挂着 —— 下一轮会重复判")
        if got.get("stop") or _stopped(ctx, impl) or session.stop_requested:
            msgs.append(f"有真进展却判了收工：{got.get('reason')!r}")
        if "整轮扫描复核" not in log or "橙悚机兵" not in log:
            msgs.append(f"判进展没有可复核的日志（新解锁名单）：{log[-300:]!r}")
    impl.reset_sessions()
    return msgs


def probe_lords_round_gain_real_progress() -> bool:
    """★挂点 31★ 完整扫描间的真进展要认（1/4 → 3/4 ⇒ round_gained + no_progress 归零）。"""
    return _gain_real_progress_failures() == []


def _gain_truly_idle_failures(impl=None) -> list:
    """★挂点 32★ 真无进展仍要收工（防过度放宽）：两次完整扫描读数完全一致。

    ★这是 ①② 的反向守卫★：把「战后单帧不判进展」修过头最容易变成「永远不收工」——
    连续两轮的**完整扫描**（无 dropped、行集与 N/M 都可比）读数完全一致 ⇒ 第 2 次判出
    ``"flat"`` 时**必须**当场按「连续 2 轮没有新解锁」收工（关轮那帧已不判进展，等它就等于永远等不到）。
    """
    impl = _impl() if impl is None else impl
    fakes = _fakes()
    msgs: list = []
    task = 122703
    impl.reset_sessions()
    with fakes.FakeClock(19000.0) as clock:
        ctx = fakes.FakeContext()
        reco = impl.LordsProgressRecognition()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is None:
            return ["取不到导航状态（_nav_state）—— 真无进展守卫无从注入"]
        state.complete_scan(session.round_index, clock.now)
        _scan_read(impl, fakes, reco, ctx, task, session, SCAN_A_ROWS)   # 基线

        for round_no in (1, 2):
            session.sessions_played = round_no                  # 这一轮真打了 1 场
            session.attempts_since_read = 1
            with contextlib.redirect_stdout(io.StringIO()):
                _post_fight_read(
                    impl, fakes, reco, ctx, task, session, POST_FIGHT_CLEAN_FRAME
                )
            if session.round_index != round_no:
                msgs.append(
                    f"第 {round_no} 轮没关成：round_index={session.round_index}"
                    f"（关轮本身不许丢）"
                )
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                scan = _detail(
                    _scan_read(impl, fakes, reco, ctx, task, session, SCAN_A_ROWS)
                )
            log = buf.getvalue()
            if round_no == 1:
                if scan.get("round_gain") != "flat":
                    msgs.append(
                        f"第 2 次完整扫描（读数一致）应判 flat，实际 round_gain="
                        f"{scan.get('round_gain')!r}"
                    )
                if session.no_progress_rounds != 1:
                    msgs.append(
                        f"第 1 次「无新解锁」应累加到 1 轮，实际 {session.no_progress_rounds}"
                    )
                if scan.get("stop") or _stopped(ctx, impl):
                    msgs.append(f"才 1 轮无新解锁就收工了：{scan.get('reason')!r}")
                continue
            # 第 2 次「无新解锁」⇒ 必须收工，且原因含「连续 2 轮没有新解锁」
            if session.no_progress_rounds != 2:
                msgs.append(
                    f"★第 2 次「无新解锁」没累加到 2 轮★：{session.no_progress_rounds}"
                )
            reason = str(scan.get("reason") or "")
            if not scan.get("stop"):
                msgs.append(
                    f"★连续 2 轮完整扫描读数一致却没停★：detail.stop={scan.get('stop')!r} "
                    f"reason={reason!r}（防过度放宽的反向守卫）"
                )
            if "连续 2 轮没有新解锁" not in reason:
                msgs.append(f"收工原因不含「连续 2 轮没有新解锁」：{reason!r}")
            if "收工：" not in log:
                msgs.append(f"收工没打「收工：」那行日志（D4 用户可见原因）：{log[-300:]!r}")
            if not session.stop_requested:
                msgs.append("收工了却没置「已判收工」—— 动作会去点一个空框")
            if not _stopped(ctx, impl):
                msgs.append(
                    f"★收工没有 override 到 {impl.STOP_NODE}★（兜底被删过头 = 永不停机）："
                    f"overrides={ctx.overrides}"
                )
    impl.reset_sessions()
    return msgs


def probe_lords_round_gain_truly_idle() -> bool:
    """★挂点 32★ 真无进展仍要收工：两次完整扫描读数完全一致 ⇒ 「连续 2 轮没有新解锁」。"""
    return _gain_truly_idle_failures() == []


