def _norm_tier_rows(rows) -> tuple:
    """``detail_tier_rows`` 的可比较形状（真源 / 安装态快照各跑一遍后必须逐项相等）。"""
    out = []
    for row in rows or ():
        box = getattr(row, "name_box", None)
        mark = getattr(row, "mark_box", None)
        out.append(
            (
                str(getattr(row, "difficulty", "")),
                str(getattr(row, "label", "")),
                tuple(box) if box else (),
                getattr(row, "status", None),
                tuple(mark) if mark else None,
            )
        )
    return tuple(out)


def _norm_choice(choice) -> tuple:
    """``pick_uncleared_tier`` 的可比较形状（含人读理由与 ``summary()``）。"""
    if choice is None:
        return ("<none>",)
    box = getattr(choice, "name_box", None)
    mark = getattr(choice, "mark_box", None)
    summary = getattr(choice, "summary", None)
    return (
        str(getattr(choice, "status", None)),
        getattr(choice, "difficulty", None),
        getattr(choice, "label", None),
        tuple(box) if box else (),
        tuple(mark) if mark else None,
        bool(getattr(choice, "picked", False)),
        str(getattr(choice, "reason", "")),
        str(summary() if callable(summary) else ""),
    )


def _state_scenario(navl) -> tuple:
    """一批确定性帧 → 可比较的状态/证据观测（真源与快照必须逐项相同）。"""
    fakes = _fakes()
    out: list = []
    frames = (
        ("mode_a", MODE_FRAME_A),
        ("mode_b", MODE_FRAME_B),
        ("multi_only", MULTI_ONLY_FRAME),
        ("solo_only", SOLO_ONLY_FRAME),
        ("swapped", SWAPPED_POSITION_FRAME),
        ("same_height", SAME_HEIGHT_FRAME),
        ("list", fakes.LIST_FRAME),
        ("detail", fakes.DETAIL_FRAME),
        ("team", fakes.TEAM_FRAME),
        ("city", CITY_FRAME),
        ("battle", BATTLE_FRAME),
        ("settle", SETTLE_FRAME),
        # ★过渡态（真机 484，14:5x）★：加载帧必须与真源一样判成 lords_loading，认不出的仍是 unknown。
        ("loading", LOADING_FRAME),
        ("loading_pct", LOADING_FRAME_PCT),
        ("unknown", (("Foo", [10, 10, 20, 20]),)),
    )
    for label, frame in frames:
        out.append((label, str(navl.page_state(frame)), _norm_evidence(navl.mode_evidence(frame))))
    for name in ("战斗HUD", "结算页", "编队页", "详情页", "主城"):
        out.append(
            (
                "rule:" + name,
                bool(navl.page_rule_hit(MODE_FRAME_A, name)),
                bool(navl.page_rule_hit(fakes.TEAM_FRAME, name)),
            )
        )
    out.append(("reason", navl.non_list_stuck_reason("lords_mode", 9.4)))
    out.append(("reason_team", navl.non_list_stuck_reason("lords_team", float(navl.NON_LIST_STUCK_SEC))))
    # ★#100 第 3 轮验收（真机 484）★：放闩证据 —— 真源与快照必须逐帧同结论
    out.append(
        (
            "challenge_release",
            navl.challenge_release_evidence(BATTLE_FRAME),
            navl.challenge_release_evidence(SETTLE_FRAME),
            navl.challenge_release_evidence(fakes.LIST_FRAME),
            navl.challenge_release_evidence(fakes.DETAIL_FRAME),
            navl.challenge_release_evidence(fakes.TEAM_FRAME),
            navl.challenge_release_evidence(LOADING_FRAME),
            navl.challenge_release_evidence(UNKNOWN_FRAME),
            navl.challenge_release_evidence(()),
        )
    )
    # ★#100 缺口 7/8★：正向证据 / 换点阶梯 / 无效框拒绝（真源与快照必须逐项相同）
    out.append(
        (
            "team_confirm",
            bool(navl.team_page_confirmed(fakes.TEAM_FRAME)),
            bool(navl.team_page_confirmed(MODE_FRAME_A)),
            bool(navl.team_page_confirmed(UNKNOWN_FRAME)),
            bool(navl.team_page_confirmed((("挑战", [297, 1069, 80, 47]),))),
            navl.team_anchor_hit(fakes.TEAM_FRAME),
        )
    )
    out.append(
        (
            "mode_points",
            tuple(tuple(point) for point in navl.mode_click_points(SOLO_BOX)),
            tuple(navl.mode_click_points((0, 0, 0, 0))),
            tuple(navl.mode_click_points(None)),
        )
    )
    out.append(("mode_reason", navl.mode_click_exhausted_reason()))
    # ★#100 第 9 个缺口★：加成点数确认框（真源与快照必须逐帧相同）
    out.append(
        (
            "bonus_dialog",
            _norm_dialog(navl.bonus_dialog(BONUS_DIALOG_FRAME)),
            _norm_dialog(navl.bonus_dialog(BONUS_DIALOG_SHIFTED_FRAME)),
            _norm_dialog(navl.bonus_dialog(BONUS_DIALOG_NO_DECLINE_FRAME)),
            _norm_dialog(navl.bonus_dialog(UNKNOWN_FRAME)),
        )
    )
    out.append(
        (
            "mode_reason_readback",
            navl.mode_click_exhausted_reason("lords_unknown", None),
            navl.mode_click_exhausted_reason("lords_mode", "自动续战", "note"),
        )
    )
    # ★#100 回归（解禁 0 场）★：屏幕边界判据 —— 同一批框真源与快照必须同结论。
    #   (202,1468,197,28) 就是真机误判的那一行（y+h > 1280）；(201,740,…) 是对照（在屏内）。
    out.append(
        (
            "on_screen",
            tuple(
                bool(navl.on_screen(box))
                for box in (
                    (202, 640, 197, 28),
                    (201, 740, 114, 33),
                    SYNTH_OVERFLOW_BOX,
                    (-1, 640, 197, 28),
                    (600, 640, 197, 28),
                    (202, 1200, 197, 28),
                    (0, 0, 720, 1280),
                    (0, 0, 721, 1280),
                    None,
                )
            ),
        )
    )
    # ★#100 第二轮验收（真机 484）★：列表行 ROI —— 同一批框真源与快照必须同结论。
    #   模式页领主名标题 [157,154,379,94]（中心 346.5,201）必须为假；真机行框必须为真。
    out.append(
        (
            "row_roi",
            tuple(
                bool(navl.row_roi_hit(box))
                for box in (
                    LIST_ROW_BOX,
                    (201, 740, 114, 33),
                    (201, 1072, 165, 28),
                    tuple(MODE_PICK_FRAME[0][1]),
                    (135, 388, 90, 35),
                    (157, 1248, 44, 26),
                    (202, 1230, 197, 28),
                    None,
                    (202, 640),
                )
            ),
        )
    )
    # ★D6（真机 484 第 3 轮验收续）★：详情页逐档状态 —— 真源与安装态快照必须逐帧同结论：
    #   徽标配对（每档的状态）/ 选档（第一个 NEW，不是最上面）/ 全档 COMPLETE 的判决 /
    #   读不到状态时**不选**/ 回列表的【返回】框（只在详情页成立）。
    out.append(
        (
            "detail_tier_rows",
            _norm_tier_rows(navl.detail_tier_rows(DETAIL_TIER_MIXED_FRAME)),
            _norm_tier_rows(navl.detail_tier_rows(DETAIL_TIER_ALL_COMPLETE_FRAME)),
            _norm_tier_rows(navl.detail_tier_rows(DETAIL_TIER_NO_STATUS_FRAME)),
            _norm_tier_rows(navl.detail_tier_rows(())),
        )
    )
    out.append(
        (
            "detail_tier_pick",
            _norm_choice(navl.pick_uncleared_tier(DETAIL_TIER_MIXED_FRAME)),
            _norm_choice(navl.pick_uncleared_tier(DETAIL_TIER_MIXED_FRAME, "地狱级")),
            _norm_choice(navl.pick_uncleared_tier(DETAIL_TIER_TWO_NEW_FRAME, "高级+")),
            _norm_choice(navl.pick_uncleared_tier(DETAIL_TIER_TWO_NEW_FRAME)),
            _norm_choice(navl.pick_uncleared_tier(DETAIL_TIER_ALL_COMPLETE_FRAME)),
            _norm_choice(navl.pick_uncleared_tier(DETAIL_TIER_NO_STATUS_FRAME)),
            _norm_choice(navl.pick_uncleared_tier(())),
        )
    )
    out.append(
        (
            "detail_back_box",
            tuple(navl.detail_back_box(DETAIL_TIER_ALL_COMPLETE_FRAME) or ()),
            tuple(navl.detail_back_box(DETAIL_TIER_NO_STATUS_FRAME) or ()),
            tuple(navl.detail_back_box(fakes.LIST_FRAME) or ()),
            tuple(navl.detail_back_box(()) or ()),
        )
    )
    out.append(
        (
            "detail_status_text",
            navl.detail_status_text(navl.DETAIL_STATUS_COMPLETE),
            navl.detail_status_text(navl.DETAIL_STATUS_NEW),
            navl.detail_status_text(None),
            navl.detail_mark_status("MPLETE!!"),
            navl.detail_mark_status("COMPLETE!!"),
            navl.detail_mark_status("NEW"),
            navl.detail_mark_status("首次报酬"),
            navl.detail_tier_name("机工神兵菲诺梅那高级+"),
            navl.detail_tier_name("机工神兵菲诺梅那超级"),
            navl.detail_tier_name("妖狐讨伐"),
            navl.detail_tier_name("推荐编成"),
        )
    )
    # ★本票最后一个阻塞点 ②（真机 484 第 5 轮验收）★：**徽标不是行名** —— 真源与安装态快照
    # 必须对同一批文本给出**同一结论**（含弱读 ``PLETE!!`` / 连串 ``COMPLETE!! SS`` / 真行名）。
    out.append(
        (
            "badge_text",
            tuple(
                bool(navl.is_badge_text(text))
                for text in (
                    "COMPLETE!!",
                    "MPLETE!!",
                    "PLETE!!",
                    "NEW",
                    "首次报酬",
                    "SS",
                    "COMPLETE!! SS",
                    "妖狐讨伐",
                    "无猾机兵",
                    "艾基尔·嫉妒讨伐",
                    "",
                    "   ",
                )
            ),
        )
    )
    # ★#100 第 8 轮★：行名被读成徽标 ⇒ **修复真名** —— 真源与安装态快照必须对同一批真机帧
    # 逐项同结论（含：正常修复 / 花名册外活动行 / 无真名返回 None / 副标题排除 / 坏框返回 None）。
    badge_probes = (
        (BADGE_MM_FRAME, [547, 689, 126, 28]),
        (BADGE_MM_FRAME, [549, 1124, 125, 24]),
        (BADGE_MIXED_FRAME, [549, 723, 126, 28]),
        (BADGE_JIANG_LIN_FRAME, [547, 688, 123, 28]),
        (BADGE_UNRECOVERABLE_FRAME, [547, 688, 127, 28]),
        (BADGE_CHROME_ONLY_FRAME, [547, 688, 127, 28]),
        (BADGE_ONLY_FRAME, [547, 688, 127, 28]),
        ((), [547, 688, 127, 28]),
        (BADGE_MM_FRAME, None),
    )

    def _norm_badge(found):
        if found is None:
            return None
        return (str(found[0]), tuple(int(value) for value in found[1]))

    out.append(
        (
            "badge_recover",
            tuple(
                _norm_badge(navl.recover_badge_row_name(frame, box))
                for frame, box in badge_probes
            ),
        )
    )
    return tuple(out)


def _parity_failures(impl=None, nav=None) -> list:
    """★安装态单源★：快照 == 真源（常量 + 判据表 == page_rules + 行为表）。"""
    impl = _impl() if impl is None else impl
    nav = _lords_nav() if nav is None else nav
    rules = _page_rules()
    snap = getattr(impl, "_NavSnapshotLogic", None)
    if snap is None:
        return ["agent/lords_impl 缺 _NavSnapshotLogic —— 安装态没有导航真源替身"]
    msgs: list = []

    # (a) 常量逐项
    for name in STATE_PARITY_FIELDS:
        want, got = getattr(nav, name, None), getattr(snap, name, None)
        if name == "LORDS_PAGE_RULES":
            continue                       # 单独按字段比（dict 的形状不同：tuple vs list）
        if got != want:
            msgs.append(f"导航快照 {name} = {got!r} != 真源 {want!r}")
    # 详情页档名正则（编译对象按 pattern 比，避免 re 缓存/对象身份干扰）
    want_re = getattr(nav, "DETAIL_TIER_NAME_RE", None)
    got_re = getattr(snap, "DETAIL_TIER_NAME_RE", None)
    if getattr(want_re, "pattern", None) != getattr(got_re, "pattern", None):
        msgs.append(
            f"导航快照 DETAIL_TIER_NAME_RE = {getattr(got_re, 'pattern', None)!r} "
            f"!= 真源 {getattr(want_re, 'pattern', None)!r}"
        )

    # (b) 判据表：真源 == scene/page_rules.py（ADR-0003）+ 快照 == 真源
    want_rules = {
        name: dict(rules.page_rule(name).recognition) for name in nav.LORDS_PAGE_RULE_NAMES
    }
    if dict(nav.LORDS_PAGE_RULES) != want_rules:
        msgs.append(
            f"scene/lords_nav.LORDS_PAGE_RULES != scene/page_rules.py 的同名判据："
            f"{dict(nav.LORDS_PAGE_RULES)!r} vs {want_rules!r} —— 判据必须按名引用 page_rules（ADR-0003）"
        )
    snap_rules = {name: dict(rec) for name, rec in dict(getattr(snap, "LORDS_PAGE_RULES", {})).items()}
    if snap_rules != want_rules:
        msgs.append(f"安装态快照的页面判据表 != page_rules：{snap_rules!r} vs {want_rules!r}")
    if tuple(getattr(snap, "LORDS_PAGE_RULE_NAMES", ())) != tuple(nav.LORDS_PAGE_RULE_NAMES):
        msgs.append(
            f"导航快照 LORDS_PAGE_RULE_NAMES = {getattr(snap, 'LORDS_PAGE_RULE_NAMES', None)!r} "
            f"!= 真源 {nav.LORDS_PAGE_RULE_NAMES!r}"
        )

    # (c) 状态名不许出现别的场景的词（快照也要）
    snap_blob = " ".join(str(n) for n in getattr(snap, "LORDS_STATES", ())) + " " + str(
        getattr(snap, "LORDS_STATE_MODE", "")
    )
    for word in FORBIDDEN_STATE_WORDS:
        if word.lower() in snap_blob.lower():
            msgs.append(f"安装态快照的状态词表里出现了别的场景的状态名（{word!r}）：{snap_blob!r}")

    # (d) 行为表：同一批帧分别跑真源与快照
    mine = _state_scenario(nav)
    theirs = _state_scenario(snap)
    for a, b in zip(mine, theirs):
        if a != b:
            msgs.append(f"页面状态行为表不一致：真源 {a!r} / 快照 {b!r}")
    if len(mine) != len(theirs):
        msgs.append(f"页面状态行为表长度不一致：{len(mine)} vs {len(theirs)}")
    labels = tuple(item[0] for item in mine)
    for must in (
        "mode_a",
        "mode_b",
        "multi_only",
        "list",
        "battle",
        "settle",
        # ★过渡态（真机 484，14:5x）★：加载帧必须同一结论（真源 vs 安装态快照）
        "loading",
        "loading_pct",
        "reason",
        # ★#100 第 3 轮验收（真机 484）★：放闩证据（真源与安装态快照逐帧同结论）
        "challenge_release",
        "team_confirm",
        "mode_points",
        "mode_reason",
        # ★#100 回归★：屏幕边界判据（越界行不许算「在屏上」）
        "on_screen",
        # ★#100 第二轮验收★：列表行 ROI（标题/页签/底栏不是列表行）
        "row_roi",
        # ★D6（真机 484 第 3 轮验收续）★：详情页逐档状态 / 选档 / 回列表的【返回】
        "detail_tier_rows",
        "detail_tier_pick",
        "detail_back_box",
        "detail_status_text",
        # ★本票最后一个阻塞点 ②★：徽标不是行名（真源与安装态快照同结论）
        "badge_text",
        # ★#100 第 8 轮★：行名修复（真机帧 / 花名册外活动行 / 无真名 / 副标题排除 / 坏框，
        # 真源与快照同结论）
        "badge_recover",
    ):
        if must not in labels:
            msgs.append(f"页面状态行为表没走到 {must!r}（剧本被删空 = 守卫瞎了）")

    # (e) classify（lords 版）必须能认出模式页
    state = impl.classify(MODE_FRAME_A)
    if state != nav.LORDS_STATE_MODE:
        msgs.append(f"agent.lords_impl.classify(模式页) = {state!r}，应为 lords_mode")
    if "wuchong" in str(state).lower():
        msgs.append(f"agent.lords_impl.classify 返回了别的场景的状态名：{state!r}")
    return msgs


def probe_lords_mode_snapshot_parity() -> bool:
    """#100-4/5：安装态冻结副本 == 真源（常量 + page_rules + 同一批帧的行为）。"""
    return _parity_failures() == []


# ---------------------------------------------------------------------------
# 7. pipeline 接线（LordsModeSolo 在枢纽里、排在 mode=read 之前、不写死坐标）
# ---------------------------------------------------------------------------
def _wiring_failures(files: dict | None = None, impl=None) -> list:
    """``lords.json::LordsModeSolo`` 的形状 + 枢纽位置 + 不写死坐标。"""
    impl = _impl() if impl is None else impl
    files = _fakes()._pipelines() if files is None else files
    data = files.get("lords.json")
    if not isinstance(data, dict):
        return ["assets/resource/pipeline/lords.json 读不到 —— 模式页节点无从检查"]
    msgs: list = []
    node = data.get("LordsModeSolo")
    if not isinstance(node, dict):
        return ["lords.json 缺 LordsModeSolo —— 领主战模式选择页没人接"]
    reco = (node.get("recognition") or {}).get("param") or {}
    if str(reco.get("custom_recognition")) != "lords_progress":
        msgs.append(f"LordsModeSolo 的识别应是 lords_progress，实际 {reco.get('custom_recognition')!r}")
    if str((reco.get("custom_recognition_param") or {}).get("mode")) != impl.MODE_SOLO:
        msgs.append(
            f"LordsModeSolo 的识别参数缺 mode={impl.MODE_SOLO!r}"
            f"（实际 {(reco.get('custom_recognition_param') or {}).get('mode')!r}）"
        )
    act = (node.get("action") or {}).get("param") or {}
    if str(act.get("custom_action")) != "lords_unlock_step":
        msgs.append(f"LordsModeSolo 的动作应是 lords_unlock_step，实际 {act.get('custom_action')!r}")
    blob = str(node.get("action") or {})
    if "target" in blob:
        msgs.append(
            "LordsModeSolo 的动作里出现写死坐标 target —— 坐标必须来自当帧 OCR 框（绝不猜）"
        )
    if "wuchong" in str(node).lower():
        msgs.append("LordsModeSolo 引用了别的场景（wuchong）的名字 —— lords 必须走自己的判据")
    if node.get("timeout") is None or int(node.get("timeout")) > 3000:
        msgs.append(f"LordsModeSolo 的 timeout = {node.get('timeout')!r}，必须 ≤3000ms")
    if int(node.get("post_delay") or 0) > 1000:
        msgs.append(f"LordsModeSolo 的 post_delay = {node.get('post_delay')!r}，必须 ≤1000ms")
    if list(node.get("on_error") or []) != ["LordsEntry"]:
        msgs.append(f"LordsModeSolo.on_error 必须回枢纽，实际 {node.get('on_error')!r}")
    nxt = list(node.get("next") or [])
    if not nxt or nxt[-1] != "LordsEntry":
        msgs.append(f"LordsModeSolo.next 末项应回枢纽 LordsEntry，实际 {nxt[-1] if nxt else None!r}")
    if "LordsEntry" not in nxt:
        msgs.append("LordsModeSolo.next 里没有枢纽 —— 点完它就没法复核/继续")

    hub_next = list((data.get("LordsEntry") or {}).get("next") or [])
    if "LordsModeSolo" not in hub_next:
        msgs.append("LordsEntry.next 里没有 LordsModeSolo —— 枢纽扫不到它，链路断开")
    else:
        i_mode = hub_next.index("LordsModeSolo")
        i_read = hub_next.index("LordsReadProgress") if "LordsReadProgress" in hub_next else -1
        if i_read >= 0 and i_mode > i_read:
            msgs.append(
                f"LordsModeSolo（第 {i_mode} 项）排在 LordsReadProgress（第 {i_read} 项）之后 —— "
                f"票面要求**在 mode=read 之前**把它接进枢纽"
            )
        i_pick = hub_next.index("LordsPickTarget") if "LordsPickTarget" in hub_next else -1
        if i_pick >= 0 and i_pick > i_mode:
            msgs.append("LordsModeSolo 排在了 LordsPickTarget 之前 —— 会抢在选行前面点模式页")
    return msgs


def probe_lords_mode_wiring() -> bool:
    """#100-4：``lords.json::LordsModeSolo`` 接线（枢纽位置 / 参数 / 不写死坐标 / 节拍）。"""
    return _wiring_failures() == []


# ---------------------------------------------------------------------------
# 8. ★#100 回归（2026-10-18，领主解禁 0 场）★：「点不出去」死线的口径
# ---------------------------------------------------------------------------
def _scanned_rows() -> tuple:
    """守卫用的「两个页签扫下来的读数」（``RowReading``；坐标只是占位，合成帧自己算）。"""
    lu = _fakes()._lords_unlock()
    return tuple(
        lu.RowReading(name, n, m, (0, 0, 1, 1), (0, 0, 1, 1))
        for name, n, m in STUCK_SCANNED_ROWS
    )


def _synth_items(impl) -> tuple:
    """走**生产同一条路**把读数还原成合成帧（``agent/lords_impl._synthesize_items``）。"""
    return tuple(impl._synthesize_items(_scanned_rows()))


def _synth_stuck_failures(impl=None, nav=None) -> list:
    """① 合成帧**不参与**「点不出去」死线（#100 回归：解禁 0 场）。

    两条都要成立：
    (a) 直接判 ``_stuck_reason``：y=1468 的行**不能**被说成「行就在屏上」，必须说「不在屏上」；
    (b) 死线已过期时 ``_read(synthesized=True)``（= ``mode=end`` 的交接帧）**不许收工**。
    """
    impl = _impl() if impl is None else impl
    nav = _lords_nav() if nav is None else nav
    fakes = _fakes()
    lu = fakes._lords_unlock()
    msgs: list = []
    task = 122101
    impl.reset_sessions()

    synth = _synth_items(impl)
    if len(synth) != len(STUCK_SCANNED_ROWS) * 2:
        return [f"合成帧项数 = {len(synth)}，应为 {len(STUCK_SCANNED_ROWS) * 2}（行名 + 通关数）"]
    got_box = tuple(synth[14][1])                     # 第 8 行（index 7）的行名框
    if got_box != SYNTH_OVERFLOW_BOX:
        return [
            f"合成帧第 8 行的行框 = {got_box!r}，应为 {SYNTH_OVERFLOW_BOX!r} —— "
            f"SYNTH_TOP_Y + 7*144 的坐标漂了，这条守卫会失效"
        ]

    with fakes.FakeClock(2000.0) as clock:
        ctx = fakes.FakeContext()
        reco = impl.LordsProgressRecognition()
        session = impl._session(task)
        session.targets = [lu.Target("苍叹机兵", None, 1, 4)]     # = 合成帧第 8 行
        session.last_click_at = clock.now - (impl.STUCK_SEC + 40.0)
        state = impl._nav_state(session)
        if state is not None:
            # 扫描已收尾：即使误让死线在合成帧上求值，也不该被「扫描闸」挡住（否则守卫测不到）
            state.complete_scan(session.round_index, clock.now)

        # (a) 越界行：不许说「行就在屏上」
        reason = str(reco._stuck_reason(session, synth) or "")
        if not reason:
            msgs.append(
                "越界行（y=1468 > 1280）在死线过期时没给出任何理由 —— 死线被整体放行了？"
            )
        if "不在屏上" not in reason:
            msgs.append(
                f"越界行的理由没说「不在屏上」（真机误判的那一句是「行就在屏上」）：{reason!r}"
            )
        if "行就在屏上" in reason:
            msgs.append(
                f"★越界行仍被断言「行就在屏上」★（行框 {list(SYNTH_OVERFLOW_BOX)}，y+h > {nav.SCREEN_H}）"
                f"—— 这正是解禁 0 场那条误收工：{reason!r}"
            )

        # (b) 交接帧：死线已过期，但这是合成帧 ⇒ 不许收工
        result = reco._read(
            synth,
            ctx,
            fakes.FakeArgv(task_id=task, node_name="LordsListEnd"),
            session,
            lu,
            synthesized=True,
        )
        detail = _detail(result)
        if detail.get("stop"):
            msgs.append(
                f"★合成帧上触发了「点不出去」收工★（{detail.get('reason')!r}）"
                f"—— mode=end 的交接帧不是真实屏幕，任务会永远走不到 pick"
            )
    impl.reset_sessions()
    return msgs


def probe_lords_synth_frame_no_stuck() -> bool:
    """#100 回归：合成帧不参与「点不出去」死线 + 越界行不算「行在屏上」。"""
    return _synth_stuck_failures() == []


def _scan_time_failures(impl=None) -> list:
    """② 扫描 60s **不算**「点不出去」：交接给 pick 时基准必须重置。"""
    impl = _impl() if impl is None else impl
    fakes = _fakes()
    lu = fakes._lords_unlock()
    msgs: list = []
    task = 122102
    impl.reset_sessions()
    synth = _synth_items(impl)

    with fakes.FakeClock(3000.0) as clock:
        ctx = fakes.FakeContext()
        reco = impl.LordsProgressRecognition()
        session = impl._session(task)
        session.last_click_at = clock.now            # 「点页签」那一瞬的基准
        state = impl._nav_state(session)
        if state is not None:
            state.complete_scan(session.round_index, clock.now)
        clock.advance(60.0)                          # 模拟扫两个页签 60s、一次点击都没有

        # 交接：扫完 → mode=read(synthesized=True)
        handoff = reco._read(
            synth,
            ctx,
            fakes.FakeArgv(task_id=task, node_name="LordsListEnd"),
            session,
            lu,
            synthesized=True,
        )
        if _detail(handoff).get("stop"):
            msgs.append(f"扫描 60s 后交接那一帧就收工（{_detail(handoff).get('reason')!r}）")
        if session.last_click_at < clock.now - 1e-6:
            msgs.append(
                f"★交接给 pick 时没有重置「点不出去」死线基准★（last_click_at={session.last_click_at!r}，"
                f"now={clock.now!r}）—— 扫描期的 60s 会被算成「点不出去」"
            )

        # 交接后的第一个**真实抓帧**：目标行在屏上（LIST_FRAME），基准刚拨过 ⇒ 不许收工。
        # （若基准没重置，这一帧的 idle = 60s > STUCK_SEC，会当场收工 = 本票的回归形状。）
        real = reco._read(
            fakes.LIST_FRAME,
            ctx,
            fakes.FakeArgv(task_id=task),
            session,
            lu,
        )
        if _detail(real).get("stop"):
            msgs.append(
                f"★扫描 60s 交接给 pick，第一帧真实抓帧就收工★（{_detail(real).get('reason')!r}）"
                f"—— 扫描时间被算成了「点不出去」"
            )
    impl.reset_sessions()
    return msgs


def probe_lords_scan_time_not_stuck() -> bool:
    """#100 回归：扫描期的时间不计入「点不出去」死线（交接时重置基准）。"""
    return _scan_time_failures() == []


def _real_stuck_failures(impl=None) -> list:
    """③ 真的卡住**仍要收工**（防过度放宽）：真实抓帧 + 行框在屏内 + 20s 无点击。"""
    impl = _impl() if impl is None else impl
    fakes = _fakes()
    lu = fakes._lords_unlock()
    msgs: list = []
    task = 122103
    impl.reset_sessions()

    with fakes.FakeClock(4000.0) as clock:
        ctx = fakes.FakeContext()
        reco = impl.LordsProgressRecognition()
        session = impl._session(task)
        state = impl._nav_state(session)
        if state is not None:
            state.complete_scan(session.round_index, clock.now)
        idle = impl.STUCK_SEC + 4.0
        session.last_click_at = clock.now - idle      # 死线已过 4s

        result = reco._read(
            REAL_ON_SCREEN_FRAME,
            ctx,
            fakes.FakeArgv(task_id=task),
            session,
            lu,
        )
        detail = _detail(result)
        reason = str(detail.get("reason") or "")
        if detail.get("stop") is not True:
            msgs.append(
                f"真实帧上卡住 {idle:.0f}s 却没判收工（{reason!r}）—— 死线被改坏了（放行过头）"
            )
        if "点不出去" not in reason:
            msgs.append(f"收工原因没写「点不出去」（现场无法区分病因）：{reason!r}")
        if "行就在屏上" not in reason:
            msgs.append(
                f"行框 y=740 明明在 720x1280 屏内，收工理由却没写「行就在屏上」（文案没带量）：{reason!r}"
            )
        if f"{idle:.0f}s" not in reason:
            msgs.append(f"收工原因没带「{idle:.0f}s」这个量（现场看不到卡了多久）：{reason!r}")
        overrides = [(name, list(next_nodes)) for name, next_nodes in ctx.overrides]
        if ("LordsReadProgress", [impl.STOP_NODE]) not in overrides:
            msgs.append(f"收工没有 override_next(LordsReadProgress -> {impl.STOP_NODE})：{overrides!r}")
    impl.reset_sessions()
    return msgs


def probe_lords_real_stuck_still_bounded() -> bool:
    """#100 回归：行在屏内 + 20s 点不出去 ⇒ 必须收工且原因带量（没放行过头）。"""
    return _real_stuck_failures() == []


# ---------------------------------------------------------------------------
# 9. ★#100 第二轮验收（真机 484，``debug/lords_accept3.log``）★
#    模式页标题不是列表行 + 列表页仍能找到行 + 越界是「忽略」不是「报错」
# ---------------------------------------------------------------------------
def _row_roi_data_failures(impl=None, nav=None) -> list:
    """ROI 的**来源与几何**：★引用真源（scene.options.TARGET_ROW_ROI）★，并与列表几何对齐。"""
    impl = _impl() if impl is None else impl
    nav = _lords_nav() if nav is None else nav
    opts = _options()
    msgs: list = []
    want = tuple(opts.TARGET_ROW_ROI)
    if tuple(nav.ROW_ROI) != want:
        msgs.append(
            f"scene/lords_nav.ROW_ROI = {tuple(nav.ROW_ROI)!r} != scene.options.TARGET_ROW_ROI "
            f"{want!r} —— 行名 ROI 必须引用真源（不许写第三份数字）"
        )
    x, y, w, h = nav.ROW_ROI
    if y != nav.SCROLL_PLAN.list_body[0]:
        msgs.append(
            f"行名 ROI 上边界 {y} != 列表体起点 {nav.SCROLL_PLAN.list_body[0]} —— "
            f"行名只可能在列表体里（SCROLL_PLAN.list_body 是 #36 的真机几何）"
        )
    tab_bottom = max(
        nav.TAB_ANCHORS[tab].roi[1] + nav.TAB_ANCHORS[tab].roi[3] for tab in nav.LORD_TABS
    )
    if y < tab_bottom:
        msgs.append(
            f"行名 ROI 上边界 {y} 落在页签行内/之上（页签底边 {tab_bottom}）—— "
            f"页签文字会被当成列表行"
        )
    if x < 0 or y < 0 or x + w > nav.SCREEN_W or y + h > nav.SCREEN_H:
        msgs.append(f"行名 ROI [{x},{y},{w},{h}] 越出 {nav.SCREEN_W}x{nav.SCREEN_H} 屏幕")

    # 判据的自证：真机行框在 ROI 内；模式页标题框在 ROI 外
    if not nav.row_roi_hit(LIST_ROW_BOX):
        msgs.append(
            f"真机列表行框 {LIST_ROW_BOX} 不在行名 ROI {tuple(nav.ROW_ROI)} 内 —— ROI 收得太窄"
        )
    title_box = tuple(MODE_PICK_FRAME[0][1])
    if nav.row_roi_hit(title_box):
        msgs.append(
            f"模式页领主名标题框 {title_box} 落在行名 ROI 内 —— 标题会被当成列表行"
            f"（真机连点 {MODE_TITLE_CENTER_720} 3 次的病根）"
        )
    return msgs


def _row_roi_title_failures(impl=None, nav=None) -> list:
    """★挂点 18★：模式页不许点标题 —— 真机模式页帧上 ``find_row_box`` 返回 None、
    ``_pick`` 产出的是 ``WHAT_MODE``（框 =「单人游戏」），不是 ``WHAT_ROW`` / ``(346.5,201)``。
    """
    impl = _impl() if impl is None else impl
    nav = _lords_nav() if nav is None else nav
    fakes = _fakes()
    msgs: list = _row_roi_data_failures(impl, nav)
    title_box = tuple(MODE_PICK_FRAME[0][1])
    task = 122201

    # (a) find_row_box（缺省 ROI）在模式页帧上必须返回 None（标题被忽略）
    with contextlib.redirect_stdout(io.StringIO()):
        box = impl.find_row_box(MODE_PICK_FRAME, "无猾机兵", r"^无猾机兵$")
    if box is not None:
        msgs.append(
            f"模式页帧上 find_row_box 返回了 {box!r} —— 把页顶**标题**当成了列表行"
            f"（真机就是在这里连点 {MODE_TITLE_CENTER_720} 三次）"
        )

    # (b) _pick：模式页 ⇒ WHAT_MODE（不是 WHAT_ROW、不是标题框）
    with fakes.FakeOcr(frame=MODE_PICK_FRAME), fakes.FakeClock(26000.0), fakes.FakeSleeper():
        ctx = fakes.FakeContext()
        session = impl._session(task)
        session.targets = [fakes._lords_unlock().Target("无猾机兵", None, 2, 5)]
        impl._nav_state(session).complete_scan(session.round_index, 0.0)
        log_buf = io.StringIO()
        with contextlib.redirect_stdout(log_buf):
            res = impl.LordsProgressRecognition().analyze(
                ctx,
                fakes.FakeArgv(
                    reco_param={"mode": "pick"}, task_id=task, node_name="LordsPickTarget"
                ),
            )
    detail = _detail(res)
    got_box = None if res.box is None else tuple(res.box)
    if detail.get("what") != impl.WHAT_MODE:
        msgs.append(
            f"模式页上 _pick 的 what = {detail.get('what')!r}，应为 {impl.WHAT_MODE!r} —— "
            f"tier 点完进的是模式页，必须交给 _mode（轮询 + 点「单人游戏」+ 确认框「否」），"
            f"不许走 pick_click 的 row/tier 分支"
        )
    if detail.get("what") == impl.WHAT_ROW:
        msgs.append("模式页上 _pick 仍走了 pick_click 的 row 分支 —— 就是 (346,201) 那条误点")
    if got_box != tuple(SOLO_BOX):
        msgs.append(f"模式页上 _pick 给的框 = {got_box!r}，应为「单人游戏」框 {SOLO_BOX}")
    if got_box == title_box:
        msgs.append(f"模式页上 _pick 给的框 == 领主名标题框 {title_box} —— 误点复活")
    if detail.get("state") != nav.LORDS_STATE_MODE:
        msgs.append(f"模式页上 _pick 的 detail.state = {detail.get('state')!r}，应为 lords_mode")
    log = log_buf.getvalue()
    if "分派" not in log:
        msgs.append(f"_pick 没有打「页面状态分派」的日志（现场看不出为什么没点行）：{log!r}")
    if "模式选择页" not in log:
        msgs.append(f"分派日志没说明「这是模式选择页」：{log!r}")
    impl.reset_sessions()
    return msgs


def _row_roi_list_failures(impl=None, nav=None) -> list:
    """★挂点 19★：列表页仍能找到行 —— 真机行框 ``[202,748,197,28]`` ⇒ ``find_row_box``
    正常返回、``pick_click`` 给 ``WHAT_ROW`` 步（ROI 不许把**真的行**也挡掉）。
    """
    impl = _impl() if impl is None else impl
    fakes = _fakes()
    msgs: list = []

    box = impl.find_row_box(LIST_ROW_FRAME, LIST_ROW_NAME, r"^妖狐讨伐$")
    if box is None:
        msgs.append(
            f"列表页帧上 find_row_box 找不到「{LIST_ROW_NAME}」（行框 {LIST_ROW_BOX}）—— "
            f"ROI 把**真的行**也挡掉了"
        )
    elif tuple(box) != LIST_ROW_BOX:
        msgs.append(f"列表页 find_row_box = {tuple(box)!r}，应为真机行框 {LIST_ROW_BOX}")

    target = fakes._lords_unlock().Target(LIST_ROW_NAME, "高级", 2, 4)
    step = impl.pick_click(
        LIST_ROW_FRAME, target, row_regex=r"^妖狐讨伐$", detail=_NoDetail()
    )
    if step is None:
        msgs.append("列表页上 pick_click 没给出任何可点步骤 —— 目标行又被 ROI 挡掉了")
    elif step.what != impl.WHAT_ROW or tuple(step.box) != LIST_ROW_BOX:
        msgs.append(
            f"列表页 pick_click = ({step.what!r}, {tuple(step.box)!r})，"
            f"应为 ({impl.WHAT_ROW!r}, {LIST_ROW_BOX})"
        )
    return msgs


def _row_roi_ignore_failures(impl=None, nav=None) -> list:
    """★挂点 20★：越界是「**忽略**」不是「报错」—— 不抛异常、不产生点击、日志可查。"""
    impl = _impl() if impl is None else impl
    fakes = _fakes()
    msgs: list = []
    title_box = tuple(MODE_PICK_FRAME[0][1])
    task = 122202

    buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(buf):
            box = impl.find_row_box(MODE_PICK_FRAME, "无猾机兵", r"^无猾机兵$")
    except Exception as exc:  # noqa: BLE001 - 越界必须只是「忽略」，不许抛
        return [f"越界的同名匹配抛了异常（{type(exc).__name__}: {exc}）—— 必须只是「忽略」"]
    if box is not None:
        msgs.append(f"越界匹配没有被忽略：find_row_box 返回了 {box!r}")
    log = buf.getvalue()
    for needle in ("忽略", "ROI", "无猾机兵"):
        if needle not in log:
            msgs.append(
                f"越界被忽略时日志缺 {needle!r}（现场查不到为什么没点这一下）：{log!r}"
            )

    # 不产生点击：动作点的是「单人游戏」中心，不是标题中心 (346.5, 201)
    with fakes.FakeOcr(frame=MODE_PICK_FRAME), fakes.FakeClock(27000.0), fakes.FakeSleeper():
        ctx = fakes.FakeContext()
        session = impl._session(task)
        session.targets = [fakes._lords_unlock().Target("无猾机兵", None, 2, 5)]
        impl._nav_state(session).complete_scan(session.round_index, 0.0)
        with contextlib.redirect_stdout(io.StringIO()):
            res = impl.LordsProgressRecognition().analyze(
                ctx,
                fakes.FakeArgv(
                    reco_param={"mode": "pick"}, task_id=task, node_name="LordsPickTarget"
                ),
            )
        with _ladder_env(impl, [fakes.TEAM_FRAME]) as calls:
            ok = impl.LordsUnlockAction().run(
                ctx, fakes.FakeArgv(task_id=task, box=res.box)
            )
    if not ok:
        msgs.append("模式页上动作没有点成（应点「单人游戏」后读到编队页）")
    for cx, cy in calls:
        if (
            abs(cx - MODE_TITLE_CENTER_720[0]) <= 1
            and abs(cy - MODE_TITLE_CENTER_720[1]) <= 1
        ):
            msgs.append(f"动作点到了领主名标题中心 {MODE_TITLE_CENTER_720} —— 误点复活")
    want = _center(SOLO_BOX)
    if not calls or abs(calls[0][0] - want[0]) > 1 or abs(calls[0][1] - want[1]) > 1:
        msgs.append(
            f"动作第一个点 = {calls[0] if calls else None}，应为「单人游戏」中心 {want}"
        )
    impl.reset_sessions()
    return msgs


def probe_lords_row_roi_title_not_row() -> bool:
    """#100-②：模式页标题不是列表行（ROI 越界忽略）+ ``_pick`` 分派到「单人游戏」。"""
    return _row_roi_title_failures() == []


def probe_lords_row_roi_list_still_row() -> bool:
    """#100-②：列表页仍能找到行（真机行框 ``[202,748,197,28]`` ⇒ ``WHAT_ROW`` 步）。"""
    return _row_roi_list_failures() == []


def probe_lords_row_roi_ignore() -> bool:
    """#100-②：越界是「忽略」不是「报错」—— 不抛、不点，日志可查。"""
    return _row_roi_ignore_failures() == []


